+using Microsoft.AspNetCore.Identity;
+using Microsoft.EntityFrameworkCore;
+using ShipmentTracker.Client.Models;
+using ShipmentTracker.Data;
+
+namespace ShipmentTracker.Endpoints;
+
+public static class ShipmentEndpoints
+{
+    public static void MapShipmentEndpoints(this WebApplication app)
+    {
+        var group = app.MapGroup("/api/shipments").RequireAuthorization();
+
+        // GET all shipments (dispatchers only)
+        group.MapGet("/", async (ApplicationDbContext db) =>
+        {
+            var shipments = await db.Shipments
+                .OrderByDescending(s => s.CreatedUtc)
+                .Select(s => s.ToDto())
+                .ToListAsync();
+            return Results.Ok(shipments);
+        }).RequireAuthorization("Dispatcher");
+
+        // GET shipment by tracking number (any authenticated user)
+        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
+        {
+            var shipment = await db.Shipments
+                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
+            return shipment is null ? Results.NotFound() : Results.Ok(shipment.ToDto());
+        });
+
+        // GET shipments for current customer
+        group.MapGet("/my", async (ApplicationDbContext db, HttpContext ctx) =>
+        {
+            var email = ctx.User.Identity?.Name ?? string.Empty;
+            var shipments = await db.Shipments
+                .Where(s => s.CustomerEmail == email)
+                .OrderByDescending(s => s.CreatedUtc)
+                .Select(s => s.ToDto())
+                .ToListAsync();
+            return Results.Ok(shipments);
+        });
+
+        // PUT update status (dispatchers only)
+        group.MapPut("/{id:int}/status", async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
+        {
+            var shipment = await db.Shipments.FindAsync(id);
+            if (shipment is null) return Results.NotFound();
+            shipment.Status = request.NewStatus;
+            await db.SaveChangesAsync();
+            return Results.Ok(shipment.ToDto());
+        }).RequireAuthorization("Dispatcher");
+
+        // POST create shipment (dispatchers only)
+        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db) =>
+        {
+            var shipment = new Shipment
+            {
+                TrackingNumber = dto.TrackingNumber,
+                Origin = dto.Origin,
+                Destination = dto.Destination,
+                Status = dto.Status,
+                CreatedUtc = DateTime.UtcNow,
+                EstimatedDeliveryUtc = dto.EstimatedDeliveryUtc,
+                CustomerEmail = dto.CustomerEmail,
+                Description = dto.Description
+            };
+            db.Shipments.Add(shipment);
+            await db.SaveChangesAsync();
+            return Results.Created($"/api/shipments/track/{shipment.TrackingNumber}", shipment.ToDto());
+        }).RequireAuthorization("Dispatcher");
+    }
+}
