using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();
        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();

        await db.Database.MigrateAsync();

        // Ensure Dispatcher role exists
        if (!await roleManager.RoleExistsAsync("Dispatcher"))
        {
            await roleManager.CreateAsync(new IdentityRole("Dispatcher"));
        }

        // Create a demo dispatcher account
        const string dispatcherEmail = "dispatcher@shipments.local";
        if (await userManager.FindByEmailAsync(dispatcherEmail) is null)
        {
            var dispatcher = new ApplicationUser
            {
                UserName = dispatcherEmail,
                Email = dispatcherEmail,
                EmailConfirmed = true
            };
            await userManager.CreateAsync(dispatcher, "Dispatch1!");
            await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
        }

        // Create a demo customer account
        const string customerEmail = "customer@example.com";
        if (await userManager.FindByEmailAsync(customerEmail) is null)
        {
            var customer = new ApplicationUser
            {
                UserName = customerEmail,
                Email = customerEmail,
                EmailConfirmed = true
            };
            await userManager.CreateAsync(customer, "Customer1!");
        }

        // Seed shipments if empty
        if (!await db.Shipments.AnyAsync())
        {
            var now = DateTime.UtcNow;
            db.Shipments.AddRange(
                new Shipment
                {
                    TrackingNumber = "SHP-1001",
                    Origin = "New York, NY",
                    Destination = "Los Angeles, CA",
                    Status = ShipmentStatus.InTransit,
                    CreatedUtc = now.AddDays(-3),
                    EstimatedDeliveryUtc = now.AddDays(2),
                    CustomerEmail = customerEmail,
                    Description = "Electronics — 2 pallets"
                },
                new Shipment
                {
                    TrackingNumber = "SHP-1002",
                    Origin = "Chicago, IL",
                    Destination = "Miami, FL",
                    Status = ShipmentStatus.Pending,
                    CreatedUtc = now.AddDays(-1),
                    EstimatedDeliveryUtc = now.AddDays(5),
                    CustomerEmail = customerEmail,
                    Description = "Furniture — 1 container"
                },
                new Shipment
                {
                    TrackingNumber = "SHP-1003",
                    Origin = "Seattle, WA",
                    Destination = "Denver, CO",
                    Status = ShipmentStatus.Delivered,
                    CreatedUtc = now.AddDays(-10),
                    EstimatedDeliveryUtc = now.AddDays(-5),
                    CustomerEmail = "other@example.com",
                    Description = "Medical supplies"
                },
                new Shipment
                {
                    TrackingNumber = "SHP-1004",
                    Origin = "Houston, TX",
                    Destination = "Phoenix, AZ",
                    Status = ShipmentStatus.OutForDelivery,
                    CreatedUtc = now.AddDays(-2),
                    EstimatedDeliveryUtc = now,
                    CustomerEmail = customerEmail,
                    Description = "Auto parts — fragile"
                },
                new Shipment
                {
                    TrackingNumber = "SHP-1005",
                    Origin = "Boston, MA",
                    Destination = "Atlanta, GA",
                    Status = ShipmentStatus.PickedUp,
                    CreatedUtc = now,
                    EstimatedDeliveryUtc = now.AddDays(4),
                    CustomerEmail = "other@example.com",
                    Description = "Clothing — 3 boxes"
                }
            );
            await db.SaveChangesAsync();
        }
    }
}

