                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                value="@s.Status"
                                @onchange="e => UpdateStatus(s, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(s.Status == status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private string? errorMessage;
    private bool showCreateForm;
    private ShipmentDto newShipment = new();
    private DateTime? estimatedDelivery;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
        {
            if (!string.IsNullOrEmpty(statusFilter) && s.Status.ToString() != statusFilter)
                return false;
            if (!string.IsNullOrEmpty(filterText))
            {
                var f = filterText.ToLowerInvariant();
                return s.TrackingNumber.Contains(f, StringComparison.OrdinalIgnoreCase)
                    || s.Destination.Contains(f, StringComparison.OrdinalIgnoreCase)
                    || s.Status.ToString().Contains(f, StringComparison.OrdinalIgnoreCase);
            }
            return true;
        }) ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            try
            {
                var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status",
                    new UpdateShipmentStatusRequest { NewStatus = newStatus });
                if (response.IsSuccessStatusCode)
                {
                    shipment.Status = newStatus;
                }
            }
            catch (Exception ex)
            {
                errorMessage = $"Update failed: {ex.Message}";
            }
        }
    }

    private void ShowCreateForm()
    {
        newShipment = new ShipmentDto();
        estimatedDelivery = DateTime.UtcNow.AddDays(5);
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        newShipment.EstimatedDeliveryUtc = estimatedDelivery;
        try
        {
            var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
            if (response.IsSuccessStatusCode)
            {
                showCreateForm = false;
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to create shipment.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Create failed: {ex.Message}";
        }
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-1001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @StatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>
                        <dt>Shipped Date (UTC)</dt>
                        <dd>@shipment.CreatedUtc.ToString("f")</dd>
                        <dt>Estimated Delivery (UTC)</dt>
                        <dd>
                            @if (shipment.EstimatedDeliveryUtc.HasValue)
                            {
                                @shipment.EstimatedDeliveryUtc.Value.ToString("f")
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                                {
                                    var remaining = shipment.EstimatedDeliveryUtc.Value - DateTime.UtcNow;
                                    if (remaining.TotalHours > 0)
                                    {
                                        <span class="text-muted ms-2">(@((int)remaining.TotalDays)d @remaining.Hours h remaining)</span>
                                    }
                                    else
                                    {
                                        <span class="text-danger ms-2">(Overdue)</span>
                                    }
                                }
                            }
                            else
                            {
                                <span class="text-muted">Not available</span>
                            }
                        </dd>
                    </dl>
                </div>
            </div>

            <!-- Progress bar -->
            <div class="mt-3">
                <h6>Delivery Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @ProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @ProgressPercent(shipment.Status)%"
                         aria-valuenow="@ProgressPercent(shipment.Status)" aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
                <div class="d-flex justify-content-between mt-1 small text-muted">
                    <span>Pending</span>
                    <span>Picked Up</span>
                    <span>In Transit</span>
                    <span>Out for Delivery</span>
                    <span>Delivered</span>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
            if (response.IsSuccessStatusCode)
            {
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            }
            else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            {
                errorMessage = $"No shipment found with tracking number '{trackingNumber}'.";
            }
            else
            {
                errorMessage = "An error occurred while searching. Please try again.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Search failed: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await SearchShipment();
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static int ProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 0,
        _ => 0
    };

    private static string ProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };
}

