@using ShipmentTracker.Client.Models
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

@if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or status…"
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary w-100" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-4">
                    <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
                <div class="col-md-4">
                    <input type="datetime-local" class="form-control" @bind="estimatedDelivery" />
                </div>
                <div class="col-12 mt-2">
                    <button class="btn btn-success me-2" @onclick="CreateShipment">Create</button>
                    <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments…</em></p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Customer</th>
                <th>Est. Delivery (UTC)</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td>@s.TrackingNumber</td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @StatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.CustomerEmail</td>
                    <td>@s.EstimatedDeliveryUtc?.ToString("g")</td>
                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                value="@s.Status"
                                @onchange="e => UpdateStatus(s, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(s.Status == status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private string? errorMessage;
    private bool showCreateForm;
    private ShipmentDto newShipment = new();
    private DateTime? estimatedDelivery;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
        {
            if (!string.IsNullOrEmpty(statusFilter) && s.Status.ToString() != statusFilter)
                return false;
            if (!string.IsNullOrEmpty(filterText))
            {
                var f = filterText.ToLowerInvariant();
                return s.TrackingNumber.Contains(f, StringComparison.OrdinalIgnoreCase)
                    || s.Destination.Contains(f, StringComparison.OrdinalIgnoreCase)
                    || s.Status.ToString().Contains(f, StringComparison.OrdinalIgnoreCase);
            }
            return true;
        }) ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            try
            {
                var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status",
                    new UpdateShipmentStatusRequest { NewStatus = newStatus });
                if (response.IsSuccessStatusCode)
                {
                    shipment.Status = newStatus;
                }
            }
            catch (Exception ex)
            {
                errorMessage = $"Update failed: {ex.Message}";
            }
        }
    }

    private void ShowCreateForm()
    {
        newShipment = new ShipmentDto();
        estimatedDelivery = DateTime.UtcNow.AddDays(5);
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        newShipment.EstimatedDeliveryUtc = estimatedDelivery;
        try
        {
            var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
            if (response.IsSuccessStatusCode)
            {
                showCreateForm = false;
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to create shipment.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Create failed: {ex.Message}";
        }
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

